function t(key){
  const lang = localStorage.getItem('etg_lang') || 'en';
  return (I18N[lang] && I18N[lang][key]) || I18N.en[key] || key;
}
function applyI18n(){
  document.querySelectorAll('[data-i18n]').forEach(el=>{ el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{ el.placeholder = t(el.dataset.i18nPh); });
}
function applyLanguage(lang){
  localStorage.setItem('etg_lang', lang);
  document.body.setAttribute('dir', lang==='fa' ? 'rtl' : 'ltr');
  document.documentElement.lang = lang;
  applyI18n();
  document.querySelectorAll('#langSeg button').forEach(b=>b.classList.toggle('on', b.dataset.l===lang));
}

/* ================= storage helpers ================= */
const LS = {
  get(k, d){ try{ return JSON.parse(localStorage.getItem(k)) ?? d }catch(e){ return d } },
  set(k, v){ localStorage.setItem(k, JSON.stringify(v)) }
};
function toast(msg){
  const el = document.getElementById('toast');
  el.textContent = msg; el.classList.add('show');
  setTimeout(()=>el.classList.remove('show'), 2200);
}
function escapeHtml(str){
  return (str||'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
const ttsSupported = 'speechSynthesis' in window;

