function icon(name){ return ICONS[name] || ''; }

/* ================= theme / font / layout ================= */
function applyTheme(theme){
  if(theme && theme!=='light') document.documentElement.setAttribute('data-theme', theme);
  else document.documentElement.removeAttribute('data-theme');
  document.querySelectorAll('#themeSeg button').forEach(b=>b.classList.toggle('on', (b.dataset.t||'light')===(theme||'light')));
}
function applyFontSize(size){
  document.documentElement.setAttribute('data-fontsize', size || 'medium');
  document.querySelectorAll('#fontSizeSeg button').forEach(b=>b.classList.toggle('on', b.dataset.fs===(size||'medium')));
}
function applyGenFont(f){
  document.documentElement.setAttribute('data-genfont', f || 'serif');
}
applyTheme(localStorage.getItem('etg_theme') || 'light');
applyFontSize(localStorage.getItem('etg_fontsize') || 'medium');
applyGenFont(localStorage.getItem('etg_genfont') || 'serif');
document.querySelectorAll('#themeSeg button').forEach(b=>b.addEventListener('click', ()=>{ localStorage.setItem('etg_theme', b.dataset.t); applyTheme(b.dataset.t); updateThemeToggleIcon(); }));
document.querySelectorAll('#fontSizeSeg button').forEach(b=>b.addEventListener('click', ()=>{ localStorage.setItem('etg_fontsize', b.dataset.fs); applyFontSize(b.dataset.fs); }));
document.getElementById('genFontSelect').addEventListener('change', e=>{ localStorage.setItem('etg_genfont', e.target.value); applyGenFont(e.target.value); });

/* ---- fill static icon placeholders ---- */
document.getElementById('settingsBtn').innerHTML = icon('settings');
document.getElementById('homeCtaIcon').innerHTML = icon('play');
document.getElementById('bnIconHome').innerHTML = icon('home');
document.getElementById('bnIconVocabulary').innerHTML = icon('flashcards');
document.getElementById('bnIconHistory').innerHTML = icon('history');
document.getElementById('bnIconTemplates').innerHTML = icon('templates');

/* ---- theme toggle (sun/moon) ---- */
function updateThemeToggleIcon(){
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  document.getElementById('themeToggleBtn').innerHTML = isDark ? icon('sun') : icon('moon');
}
document.getElementById('themeToggleBtn').addEventListener('click', ()=>{
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  const next = isDark ? 'light' : 'dark';
  localStorage.setItem('etg_theme', next);
  applyTheme(next);
  updateThemeToggleIcon();
});
updateThemeToggleIcon();

/* ---- last generated box on home ---- */
function renderLastGenBox(){
  const history = LS.get('etg_history', []);
  const box = document.getElementById('lastGenBox');
  if(!history.length){ box.style.display = 'none'; return; }
  const last = history[0];
  document.getElementById('lastGenLbl').innerHTML = icon('clock') + '<span>' + t('last_generated') + '</span>';
  document.getElementById('lastGenTitle').textContent = last.title;
  document.getElementById('lastGenPreview').textContent = (last.text||'').slice(0,90) + ((last.text||'').length>90 ? '…' : '');
  box.style.display = 'block';
  box.onclick = ()=>{ currentResult = last; renderOutput(last); goTo('generateResult'); };
}
let highlightMode = localStorage.getItem('etg_highlight_mode') || 'sentence';
document.querySelectorAll('#highlightSeg button').forEach(b=>{
  b.classList.toggle('on', b.dataset.h===highlightMode);
  b.addEventListener('click', ()=>{ highlightMode = b.dataset.h; localStorage.setItem('etg_highlight_mode', highlightMode); document.querySelectorAll('#highlightSeg button').forEach(x=>x.classList.toggle('on', x===b)); });
});

/* ================= onboarding ================= */
const onboardingScreen = document.getElementById('onboardingScreen');
const appShell = document.getElementById('appShell');
function finishOnboarding(){
  onboardingScreen.style.display = 'none';
  appShell.style.display = 'block';
  updateProviderHints();
  history.replaceState({stack:['home']}, '', '#home');
  renderLastGenBox();
}
function showOnbStep(id){
  const steps = ['onbSplash','onbLang','onbStep1','onbPuterExplain','onbPuterLoading','onbGemini','onbWelcome'];
  const current = steps.find(s=> document.getElementById(s).style.display !== 'none');
  const doSwap = ()=>{
    steps.forEach(s=>{
      const el = document.getElementById(s);
      el.style.display = (s===id) ? ((s==='onbSplash'||s==='onbPuterLoading') ? 'flex' : 'block') : 'none';
    });
    requestAnimationFrame(()=>{ document.getElementById(id).style.opacity = '1'; });
  };
  if(current && current!==id){
    document.getElementById(current).style.opacity = '0';
    document.getElementById(id).style.opacity = '0';
    setTimeout(doSwap, 260);
  } else {
    document.getElementById(id).style.opacity = '0';
    doSwap();
  }
}
