const FEMALE_HINTS = ['female','samantha','victoria','zira','susan','karen','moira','tessa','fiona','joanna','salli','kimberly','amy','emma','ava','allison','nicky','serena'];
const MALE_HINTS = ['male','daniel','alex','david','fred','george','james','justin','matthew','joey','brian','arthur','oliver','ryan'];
function guessGender(name){
  const n = (name||'').toLowerCase();
  if(FEMALE_HINTS.some(h=>n.includes(h))) return 'female';
  if(MALE_HINTS.some(h=>n.includes(h))) return 'male';
  return 'unknown';
}
function pickDefaultVoice(){
  return availableVoices[0] || null;
}
function pickVoiceByGender(gender){
  const match = availableVoices.find(v=>guessGender(v.name)===gender);
  return match || pickDefaultVoice();
}

/* ================= AI helpers ================= */
function extractPuterText(response){
  if(typeof response === 'string') return response;
  if(response?.message?.content){
    const c = response.message.content;
    if(typeof c === 'string') return c;
    if(Array.isArray(c)) return c.map(p=>p.text||'').join('');
  }
  if(typeof response?.text === 'string') return response.text;
  if(typeof response?.content === 'string') return response.content;
  return JSON.stringify(response);
}
async function callGeminiRaw(prompt, apiKey, modelName){
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(modelName)}:generateContent?key=${encodeURIComponent(apiKey)}`;
  const res = await fetch(url, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ contents:[{ parts:[{ text: prompt }] }] }) });
  if(!res.ok){ const errText = await res.text().catch(()=> ''); throw new Error('Gemini API error (' + res.status + '). ' + errText.slice(0,150)); }
  const data = await res.json();
  const text = data?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') || '';
  if(!text) throw new Error('Gemini returned an empty response.');
  return text;
}
async function callAI(prompt){
  const provider = localStorage.getItem('etg_provider') || 'puter';
  let raw;
  if(provider === 'gemini'){
    const key = localStorage.getItem('etg_gemini_key');
    const modelName = localStorage.getItem('etg_gemini_model') || 'gemini-2.0-flash';
    if(!key) throw new Error('Gemini API key is missing. Set it in Settings.');
    raw = await callGeminiRaw(prompt, key, modelName);
  } else {
    if(typeof puter === 'undefined') throw new Error('The AI service failed to load. Check your internet connection and reload the page.');
    let response;
    try{
      response = await puter.ai.chat(prompt, { model: localStorage.getItem('etg_puter_model') || 'openai/gpt-5.4-nano' });
    }catch(sdkErr){
      throw new Error('Puter had a problem answering (try again, or switch model/provider in Settings). Details: ' + (sdkErr?.message || sdkErr));
    }
    raw = extractPuterText(response);
  }
  const cleaned = raw.replace(/```json|```/g,'').trim();
  try{ return JSON.parse(cleaned); }
  catch(e){ throw new Error('Could not parse the model response as JSON. Try again.'); }
}
async function callAIText(prompt){
  const provider = localStorage.getItem('etg_provider') || 'puter';
  let raw;
  if(provider === 'gemini'){
    const key = localStorage.getItem('etg_gemini_key');
    const modelName = localStorage.getItem('etg_gemini_model') || 'gemini-2.0-flash';
    if(!key) throw new Error('Gemini API key is missing. Set it in Settings.');
    raw = await callGeminiRaw(prompt, key, modelName);
  } else {
    if(typeof puter === 'undefined') throw new Error('The AI service failed to load. Check your internet connection and reload the page.');
    let response;
    try{
      response = await puter.ai.chat(prompt, { model: localStorage.getItem('etg_puter_model') || 'openai/gpt-5.4-nano' });
    }catch(sdkErr){
      throw new Error('Puter had a problem answering (try again, or switch model/provider in Settings). Details: ' + (sdkErr?.message || sdkErr));
    }
    raw = extractPuterText(response);
  }
  return raw.replace(/```markdown/g,'```').trim();
}

/* ================= shared text helpers ================= */
const CEFR_ORDER = ['A1','A2','B1','B2','C1','C2'];
function cefrIndex(lvl){ return CEFR_ORDER.indexOf(String(lvl||'').toUpperCase()); }
function countSyllables(word){
  word = word.toLowerCase().replace(/[^a-z]/g,'');
  if(!word) return 0;
  const groups = word.match(/[aeiouy]+/g);
  let count = groups ? groups.length : 1;
  if(word.endsWith('e') && count > 1) count--;
  return Math.max(1, count);
}
function estimateLocalCEFR(text){
  const words = text.match(/[A-Za-z']+/g) || [];
  const sentences = (text.match(/[.!?]+(\s|$)/g) || []).length || 1;
  if(words.length === 0) return 'A1';
  const syllables = words.reduce((s,w)=> s + countSyllables(w), 0);
  // Flesch-Kincaid Grade Level, mapped to approximate CEFR bands
  const fkgl = 0.39 * (words.length/sentences) + 11.8 * (syllables/words.length) - 15.59;
  if(fkgl < 2) return 'A1';
  if(fkgl < 4) return 'A2';
  if(fkgl < 6) return 'B1';
  if(fkgl < 8) return 'B2';
  if(fkgl < 10) return 'C1';
  return 'C2';
}
function countWords(text){ return (text.match(/\S+/g) || []).length; }
function countSentences(text){ return (text.match(/[.!?]+(\s|$)/g) || []).length || 1; }
function splitSentences(text){
  const matches = text.match(/[^.!?]+[.!?]+(\s+|$)|[^.!?]+$/g) || [text];
  return matches.map(s=>s.trim()).filter(Boolean);
}
